-- Safety first: on a database that already holds Vio ♡ (your photos,
-- memories, messages…) this file stops right here and changes nothing.
do $$
begin
  if to_regclass('public.media') is not null then
    raise exception 'Questo database contiene già Vio ♡: setup.sql è solo per un progetto NUOVO e non è stato eseguito. Per aggiornare usa supabase/update.sql (non cancella niente).';
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- 20260927000001_schema.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Viola × Adam — schema
-- Every table lives in `public` and is protected by RLS (see the next
-- migration). Enumerations are plain text + CHECK constraints so they can
-- evolve without painful enum migrations.
-- =====================================================================

create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------------
-- Generic helpers
-- ---------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------
-- Profiles & roles
-- role: admin (Adam) | user (Viola) | pending (anyone else: no access)
-- ---------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  role text not null default 'pending' check (role in ('admin', 'user', 'pending')),
  display_name text,
  nickname text,
  onboarded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- Role lookups used by every RLS policy. SECURITY DEFINER so they can read
-- profiles without recursing into profiles' own policies.
create or replace function public.app_role()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select role from public.profiles where id = (select auth.uid());
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select role = 'admin' from public.profiles where id = (select auth.uid())), false);
$$;

create or replace function public.is_member()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select role in ('admin', 'user') from public.profiles where id = (select auth.uid())), false);
$$;

-- New auth user -> profile. The role can only be pre-assigned through
-- app_metadata, which only the service role can write (never the client).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  requested text := new.raw_app_meta_data ->> 'role';
begin
  insert into public.profiles (id, role, display_name)
  values (
    new.id,
    case when requested in ('admin', 'user') then requested else 'pending' end,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1))
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

