-- Time capsules: list without leaking the body of locked letters
create or replace function public.list_time_capsules()
returns table (
  id uuid,
  title text,
  teaser text,
  unlock_at timestamptz,
  is_unlocked boolean,
  opened_at timestamptz,
  media_id uuid
)
language sql
stable
security definer
set search_path = ''
as $$
  select c.id, c.title, c.teaser, c.unlock_at,
         c.unlock_at <= now() as is_unlocked,
         c.opened_at,
         case when c.unlock_at <= now() then c.media_id else null end
  from public.time_capsules c
  where c.is_published and (select public.is_member())
  order by c.unlock_at asc;
$$;

create or replace function public.mark_capsule_opened(capsule_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.time_capsules
     set opened_at = coalesce(opened_at, now())
   where id = capsule_id
     and is_published
     and unlock_at <= now()
     and (select public.is_member());
$$;

create or replace function public.mark_open_when_opened(card_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.open_when_cards
     set opened_count = opened_count + 1,
         last_opened_at = now()
   where id = card_id
     and is_published
     and (select public.is_member());
$$;

-- AI usage counters: members can only increment their own counters
create or replace function public.increment_ai_usage(
  p_scope text,
  p_requests integer,
  p_input_tokens integer,
  p_output_tokens integer
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (select public.is_member()) then
    raise exception 'not allowed';
  end if;
  if p_scope not in ('viola', 'copilot') or (p_scope = 'copilot' and not (select public.is_admin())) then
    raise exception 'invalid scope';
  end if;
  if p_requests < 0 or p_input_tokens < 0 or p_output_tokens < 0
     or p_requests > 20 or p_input_tokens > 2000000 or p_output_tokens > 200000 then
    raise exception 'invalid usage values';
  end if;

  insert into public.ai_usage_daily as u (day, user_id, scope, requests, input_tokens, output_tokens)
  values ((now() at time zone 'Europe/Rome')::date, (select auth.uid()), p_scope, p_requests, p_input_tokens, p_output_tokens)
  on conflict (day, user_id, scope) do update
    set requests = u.requests + excluded.requests,
        input_tokens = u.input_tokens + excluded.input_tokens,
        output_tokens = u.output_tokens + excluded.output_tokens;
end;
$$;

-- Cost control numbers for the admin dashboard
create or replace function public.admin_usage_stats()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  if not (select public.is_admin()) then
    raise exception 'not allowed';
  end if;
  select jsonb_build_object(
    'db_bytes', pg_database_size(current_database()),
    'media_bytes', coalesce((select sum(size_bytes) from public.media), 0),
    'media_count', (select count(*) from public.media),
    'notifications_month', (
      select coalesce(jsonb_object_agg(channel, n), '{}'::jsonb) from (
        select channel, count(*) as n from public.notification_events
        where created_at >= date_trunc('month', now()) and status = 'sent'
        group by channel
      ) s
    )
  ) into result;
  return result;
end;
$$;

grant execute on function public.list_time_capsules() to authenticated;
grant execute on function public.mark_capsule_opened(uuid) to authenticated;
grant execute on function public.mark_open_when_opened(uuid) to authenticated;
grant execute on function public.increment_ai_usage(text, integer, integer, integer) to authenticated;
grant execute on function public.admin_usage_stats() to authenticated;

-- ---------------------------------------------------------------------
-- 20260927000003_storage.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Viola × Adam — private storage bucket for photos and audio
--   * bucket is PRIVATE: files are served only through short-lived
--     signed URLs created for logged-in members.
--   * size + MIME are enforced by the bucket itself, and again by the app.
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'media',
  'media',
  false,
  10485760, -- 10 MB
  array[
    'image/jpeg', 'image/png', 'image/webp',
    'audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/aac', 'audio/ogg', 'audio/wav', 'audio/webm'
  ]
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Members can read a file only if it belongs to a shared media record.
create policy "media read shared" on storage.objects for select to authenticated
  using (
    bucket_id = 'media'
    and (
      (select public.is_admin())
      or (
        (select public.is_member())
        and exists (
          select 1 from public.media m
          where (m.path = storage.objects.name or m.thumb_path = storage.objects.name)
            and m.visibility = 'shared'
        )
      )
    )
  );

create policy "media admin insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and (select public.is_admin()));

create policy "media admin update" on storage.objects for update to authenticated
  using (bucket_id = 'media' and (select public.is_admin()))
  with check (bucket_id = 'media' and (select public.is_admin()));

create policy "media admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (select public.is_admin()));

-- ---------------------------------------------------------------------
-- 20260928000001_hardening.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Vio ♡ — hardening (safe to run more than once)
--
-- Postgres grants EXECUTE on every new function to PUBLIC, and a
-- per-schema "alter default privileges" cannot take that back. So the RPCs
-- created in 20260927000002 were callable by anon (they returned nothing
-- or raised "not allowed", but anon must not reach them at all).
-- =====================================================================

revoke execute on all functions in schema public from public, anon;

grant execute on function
  public.app_role(),
  public.is_admin(),
  public.is_member(),
  public.list_time_capsules(),
  public.mark_capsule_opened(uuid),
  public.mark_open_when_opened(uuid),
  public.increment_ai_usage(text, integer, integer, integer),
  public.admin_usage_stats()
to authenticated;

-- ---------------------------------------------------------------------
-- 20260928000002_privacy.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Vio ♡ — Viola decides whether Adam sees her activity (safe to re-run)
--
-- Until now every "breathing completed / fear flow / game played" event was
-- visible to the admin. Viola can now switch that off from "La tua privacy".
-- Default stays on (same behaviour as before), and the page explains it.
-- =====================================================================

alter table public.profiles add column if not exists share_activity boolean not null default true;

-- She may change only this switch (still never `role`).
grant update (share_activity) on public.profiles to authenticated;

-- ---------------------------------------------------------------------
-- 20260928000003_hearts.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Vio ♡ — "Cuore a distanza" (safe to run more than once)
--
-- One tap = "I'm thinking of you". Viola sends a heart, Adam sees it (and
-- gets a gentle, rate-limited notification) and can send one back.
-- Only the two members can see or send hearts.
-- =====================================================================

create table if not exists public.hearts (
  id uuid primary key default gen_random_uuid(),
  from_user uuid not null default auth.uid() references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  seen_at timestamptz
);
create index if not exists hearts_created_idx on public.hearts (created_at desc);

alter table public.hearts enable row level security;

revoke all on public.hearts from anon;
grant select, insert, delete on public.hearts to authenticated;
grant update (seen_at) on public.hearts to authenticated;
grant all on public.hearts to service_role;

drop policy if exists hearts_select on public.hearts;
drop policy if exists hearts_insert on public.hearts;
drop policy if exists hearts_mark_seen on public.hearts;
drop policy if exists hearts_delete_own on public.hearts;

-- a two-person exchange: both members see both directions
create policy hearts_select on public.hearts for select to authenticated
  using ((select public.is_member()));
-- you can only send hearts as yourself
create policy hearts_insert on public.hearts for insert to authenticated
  with check (from_user = (select auth.uid()) and (select public.is_member()));
-- you can only mark as seen the hearts you RECEIVED (column grant: seen_at only)
create policy hearts_mark_seen on public.hearts for update to authenticated
  using ((select public.is_member()) and from_user <> (select auth.uid()))
  with check ((select public.is_member()) and from_user <> (select auth.uid()));
-- and delete only your own (privacy: "cancella i miei dati")
create policy hearts_delete_own on public.hearts for delete to authenticated
  using (from_user = (select auth.uid()));

-- ---------------------------------------------------------------------
-- 20260929000001_readiness.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Vio ♡ — "Completa Vio ♡" checklist (safe to run more than once)
--
-- Almost every task is derived from the data that already exists. This
-- table only stores what the database cannot know: things Adam checked by
-- hand ("installed on Viola's phone", "offline tested") or optional tasks
-- marked as not needed. Admin only.
-- =====================================================================

create table if not exists public.readiness_checks (
  task_id text primary key check (task_id ~ '^[a-z0-9-]{2,60}$'),
  state text not null default 'done' check (state in ('done', 'skipped')),
  done_at timestamptz not null default now(),
  done_by uuid default auth.uid() references auth.users (id) on delete set null
);

alter table public.readiness_checks enable row level security;

revoke all on public.readiness_checks from anon;
grant select, insert, update, delete on public.readiness_checks to authenticated;
grant all on public.readiness_checks to service_role;

drop policy if exists readiness_admin_select on public.readiness_checks;
drop policy if exists readiness_admin_insert on public.readiness_checks;
drop policy if exists readiness_admin_update on public.readiness_checks;
drop policy if exists readiness_admin_delete on public.readiness_checks;

create policy readiness_admin_select on public.readiness_checks for select to authenticated
  using ((select public.is_admin()));
create policy readiness_admin_insert on public.readiness_checks for insert to authenticated
  with check ((select public.is_admin()));
create policy readiness_admin_update on public.readiness_checks for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy readiness_admin_delete on public.readiness_checks for delete to authenticated
  using ((select public.is_admin()));

-- ---------------------------------------------------------------------
-- 20260930000001_photos.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Vio ♡ — photos: place, subject position and batch editing
-- (safe to run more than once)
--
-- * media.place  — where the photo was taken (shown under the photo)
-- * media.focus  — which part to keep visible when a frame must crop the
--                  photo (centre / top / bottom / left / right)
-- * admin_batch_update_media  — edits many photos in ONE statement:
--   only the fields present in `patch` change, everything else is left
--   exactly as it was. Runs with the caller's rights (RLS applies) and
--   refuses anyone who is not the admin.
-- * admin_restore_media — "Annulla": puts back the values saved before a
--   batch, only on photos nobody touched after it.
-- =====================================================================

alter table public.media add column if not exists place text;
alter table public.media add column if not exists focus text not null default 'center';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'media_place_len') then
    alter table public.media add constraint media_place_len check (place is null or char_length(place) <= 120);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'media_focus_check') then
    alter table public.media add constraint media_focus_check check (focus in ('center', 'top', 'bottom', 'left', 'right'));
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- Batch update
-- patch keys (all optional; a missing key = "non modificare"):
--   category, taken_on, place, caption  (text / date; "" or null = empty)
--   visibility, focus                    (text, checked by the table)
--   featured, include_in_random          (boolean)
--   tags_add, tags_remove, contexts_add, contexts_remove (text arrays)
-- Returns, for every photo really updated, its previous values.
-- ---------------------------------------------------------------------
create or replace function public.admin_batch_update_media(media_ids uuid[], patch jsonb)
returns table (id uuid, previous jsonb, updated_at timestamptz)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  allowed constant text[] := array[
    'category', 'taken_on', 'place', 'caption', 'visibility', 'focus', 'featured', 'include_in_random',
    'tags_add', 'tags_remove', 'contexts_add', 'contexts_remove'
  ];
  tags_add text[] := coalesce(array(select jsonb_array_elements_text(patch -> 'tags_add')), '{}');
  tags_remove text[] := coalesce(array(select jsonb_array_elements_text(patch -> 'tags_remove')), '{}');
  ctx_add text[] := coalesce(array(select jsonb_array_elements_text(patch -> 'contexts_add')), '{}');
  ctx_remove text[] := coalesce(array(select jsonb_array_elements_text(patch -> 'contexts_remove')), '{}');
begin
  if not (select public.is_admin()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if coalesce(cardinality(media_ids), 0) = 0 or cardinality(media_ids) > 1000 then
    raise exception 'select between 1 and 1000 photos' using errcode = '22023';
  end if;
  if jsonb_typeof(patch) is distinct from 'object' or patch = '{}'::jsonb
     or exists (select 1 from jsonb_object_keys(patch) k where k <> all (allowed)) then
    raise exception 'invalid patch' using errcode = '22023';
  end if;

  return query
  with prev as (
    select m.id, m.category, m.taken_on, m.place, m.caption, m.visibility, m.focus, m.featured,
           m.include_in_random, m.tags, m.contexts, m.breathing_enabled, m.ai_avatar_enabled,
           case when patch ? 'contexts_add' or patch ? 'contexts_remove'
                then array(select distinct c from unnest(m.contexts || ctx_add) c where c <> all (ctx_remove) order by c)
                else m.contexts end as next_contexts
    from public.media m
    where m.id = any (media_ids)
    for update
  )
  update public.media m set
    category = case when patch ? 'category' then nullif(btrim(patch ->> 'category'), '') else m.category end,
    taken_on = case when patch ? 'taken_on' then nullif(patch ->> 'taken_on', '')::date else m.taken_on end,
    place = case when patch ? 'place' then nullif(btrim(patch ->> 'place'), '') else m.place end,
    caption = case when patch ? 'caption' then nullif(btrim(patch ->> 'caption'), '') else m.caption end,
    visibility = case when patch ? 'visibility' then patch ->> 'visibility' else m.visibility end,
    focus = case when patch ? 'focus' then patch ->> 'focus' else m.focus end,
    featured = case when patch ? 'featured' then (patch ->> 'featured')::boolean else m.featured end,
    include_in_random = case when patch ? 'include_in_random' then (patch ->> 'include_in_random')::boolean else m.include_in_random end,
    tags = case when patch ? 'tags_add' or patch ? 'tags_remove'
                then array(select distinct t from unnest(m.tags || tags_add) t where t <> all (tags_remove) order by t)
                else m.tags end,
    contexts = prev.next_contexts,
    -- flags always follow the contexts (same rule as the single editor)
    breathing_enabled = case when patch ? 'contexts_add' or patch ? 'contexts_remove' then 'breathing' = any (prev.next_contexts) else m.breathing_enabled end,
    ai_avatar_enabled = case when patch ? 'contexts_add' or patch ? 'contexts_remove' then 'adam_ai' = any (prev.next_contexts) else m.ai_avatar_enabled end
  from prev
  where m.id = prev.id
  returning m.id,
    jsonb_build_object(
      'category', prev.category, 'taken_on', prev.taken_on, 'place', prev.place, 'caption', prev.caption,
      'visibility', prev.visibility, 'focus', prev.focus, 'featured', prev.featured,
      'include_in_random', prev.include_in_random, 'tags', to_jsonb(prev.tags), 'contexts', to_jsonb(prev.contexts),
      'breathing_enabled', prev.breathing_enabled, 'ai_avatar_enabled', prev.ai_avatar_enabled
    ),
    m.updated_at;
end;
$$;

-- ---------------------------------------------------------------------
-- Undo a batch: `snapshot` = [{ id, <field>: <previous value>, ... }].
-- Only photos still exactly as the batch left them (updated_at unchanged)
-- are restored; the others were edited meanwhile and are left alone.
-- ---------------------------------------------------------------------
create or replace function public.admin_restore_media(snapshot jsonb, batch_updated_at timestamptz)
returns setof uuid
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not (select public.is_admin()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if jsonb_typeof(snapshot) is distinct from 'array' or jsonb_array_length(snapshot) > 1000 then
    raise exception 'invalid snapshot' using errcode = '22023';
  end if;

  return query
  update public.media m set
    category = case when s ? 'category' then s ->> 'category' else m.category end,
    taken_on = case when s ? 'taken_on' then (s ->> 'taken_on')::date else m.taken_on end,
    place = case when s ? 'place' then s ->> 'place' else m.place end,
    caption = case when s ? 'caption' then s ->> 'caption' else m.caption end,
    visibility = case when s ? 'visibility' then s ->> 'visibility' else m.visibility end,
    focus = case when s ? 'focus' then s ->> 'focus' else m.focus end,
    featured = case when s ? 'featured' then (s ->> 'featured')::boolean else m.featured end,
    include_in_random = case when s ? 'include_in_random' then (s ->> 'include_in_random')::boolean else m.include_in_random end,
    tags = case when s ? 'tags' then array(select jsonb_array_elements_text(s -> 'tags')) else m.tags end,
    contexts = case when s ? 'contexts' then array(select jsonb_array_elements_text(s -> 'contexts')) else m.contexts end,
    breathing_enabled = case when s ? 'breathing_enabled' then (s ->> 'breathing_enabled')::boolean else m.breathing_enabled end,
    ai_avatar_enabled = case when s ? 'ai_avatar_enabled' then (s ->> 'ai_avatar_enabled')::boolean else m.ai_avatar_enabled end
  from jsonb_array_elements(snapshot) s
  where m.id = (s ->> 'id')::uuid
    and m.updated_at = batch_updated_at
  returning m.id;
end;
$$;

revoke execute on function public.admin_batch_update_media(uuid[], jsonb) from public, anon;
revoke execute on function public.admin_restore_media(jsonb, timestamptz) from public, anon;
grant execute on function public.admin_batch_update_media(uuid[], jsonb) to authenticated;
grant execute on function public.admin_restore_media(jsonb, timestamptz) to authenticated;

